# Generated by Claude Opus 5.5 (claude.ai/code) · 2026-11-18
# Pester tests: event time in UTC, exact parsing, DST-safe arithmetic, coverage tolerance.

BeforeAll {
    . (Join-Path $PSScriptRoot '../TestHelpers.ps1')

    function Invoke-InZone {
        # run a snippet in a child pwsh under another time zone (.NET caches the local zone)
        param([string]$Zone, [string]$Script)
        $saved = $env:TZ
        $env:TZ = $Zone
        try {
            $mod = Join-Path $RepoDir 'src/lib/BackupCommon.psm1'
            return @(& pwsh -NoProfile -NonInteractive -c "Import-Module '$mod'; $Script" 2>&1 | ForEach-Object { [string]$_ })
        }
        finally { $env:TZ = $saved }
    }
}

AfterAll {
    Remove-TestWork
}

Describe 'event time' {
    It 'writes event timestamps and run ids in UTC' {
        Get-NowIso | Should -Match 'Z$'
        $id = New-RunId
        $utc = [datetime]::ParseExact($id.Substring(0, 15), 'yyyyMMdd-HHmmss', [System.Globalization.CultureInfo]::InvariantCulture)
        [math]::Abs(([datetime]::UtcNow - $utc).TotalSeconds) | Should -BeLessThan 5
    }

    It 'reads old local-with-offset and new UTC stamps as the same exact instant' {
        $a = ConvertFrom-EventLine ('{"ts":"2026-11-18T14:19:04.0000000+01:00","type":"x"}')
        $b = ConvertFrom-EventLine ('{"ts":"2026-11-18T13:19:04.0000000Z","type":"x"}')
        $a.ts.Kind | Should -Be 'Utc'
        $a.ts | Should -Be $b.ts
        $a.ts.ToString('o') | Should -Be '2026-11-18T13:19:04.0000000Z'
    }

    It 'measures ages across a DST change in real hours' {
        # Europe/Paris falls back on 2026-10-25: 23:00 to 23:00 local is 25 real hours
        $out = Invoke-InZone 'Europe/Paris' @'
$a = (ConvertFrom-EventLine '{"ts":"2026-10-24T23:00:00+02:00","type":"x"}').ts
$b = (ConvertFrom-EventLine '{"ts":"2026-10-25T23:00:00+01:00","type":"x"}').ts
($b - $a).TotalHours
'@
        ($out | Select-Object -Last 1) | Should -Be '25'
    }

    It 'shows times in the viewer''s zone' {
        $out = Invoke-InZone 'Europe/Paris' "Format-EventTime (ConvertFrom-EventLine '{""ts"":""2026-11-18T13:19:04Z""}').ts"
        ($out | Select-Object -Last 1) | Should -Be '2026-11-18T14:19:04+01:00'
        Invoke-InZone 'UTC' "Format-EventTime (ConvertFrom-EventLine '{""ts"":""2026-11-18T13:19:04Z""}').ts" |
            Select-Object -Last 1 | Should -Be '2026-11-18T13:19:04+00:00'
    }
}

Describe 'coverage tolerance' {
    It 'adds an hour to the margin for periods of a day or more' {
        Get-CoverageThreshold -Margin 0.02 | Should -Be 0.98
        Get-CoverageThreshold -Margin 0.02 -PeriodSeconds 3600 | Should -Be 0.98
        Get-CoverageThreshold -Margin 0.02 -PeriodSeconds 86400 | Should -BeLessThan 0.94
        [math]::Round((Get-CoverageThreshold -Margin 0.02 -PeriodSeconds (7 * 86400)), 4) | Should -Be ([math]::Round(0.98 - 3600 / (7 * 86400), 4))
    }

    It 'does not skip the daily backup on the spring DST night (23 real hours)' {
        $cfg = '{ "window": { "open": "00:00", "close": "23:59" }, "services": { "app": { "enabled": true } } }' | ConvertFrom-Json
        $now = [datetime]::new(2026, 3, 29, 22, 0, 0, [System.DateTimeKind]::Utc)
        $proj = @{ app = @{ lastSuccess = $now.AddHours(-23).AddMinutes(10); lastBytes = 0; stepDurations = @{} } }   # and a timer 10 min early
        $job = @(Get-BackupPlan -Config $cfg -Projection $proj -At $now)[0]
        $job.PeriodSeconds | Should -Be 86400
        $job.Overdue | Should -BeGreaterOrEqual (Get-CoverageThreshold -Margin 0.02 -PeriodSeconds $job.PeriodSeconds)
    }

    It 'still skips a same-day re-run' {
        $cfg = '{ "window": { "open": "00:00", "close": "23:59" }, "services": { "app": { "enabled": true } } }' | ConvertFrom-Json
        $now = [datetime]::UtcNow
        $proj = @{ app = @{ lastSuccess = $now.AddHours(-6); lastBytes = 0; stepDurations = @{} } }
        $job = @(Get-BackupPlan -Config $cfg -Projection $proj -At $now)[0]
        $job.Overdue | Should -BeLessThan (Get-CoverageThreshold -Margin 0.02 -PeriodSeconds $job.PeriodSeconds)
    }

    It 'sizes the tolerance on the service''s own interval' {
        $cfg = '{ "window": { "open": "00:00", "close": "23:59" }, "services": { "app": { "enabled": true, "targetIntervalHours": 48 } } }' | ConvertFrom-Json
        @(Get-BackupPlan -Config $cfg -At ([datetime]::UtcNow))[0].PeriodSeconds | Should -Be (48 * 3600)
    }
}
